def blockinfo(A,Q):
    b=Q.T@A@Q  # 2x2
    # decompose into scaled rotation + rest
    a=(b[0,0]+b[1,1])/2; c=(b[1,0]-b[0,1])/2
    rot=np.hypot(a,c); ang=np.degrees(np.arctan2(c,a))
